-- Insert Quiz Questions for Lesson: Apply the Payment Path to Your Business

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 11 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 11 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'apply-payment-path' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson apply-payment-path not found in module 11';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the first step in applying the payment path?', 
    '["Immediately create a payment link","Name the customer and the offer","Skip planning and start building","Delete existing products"]'::jsonb,
    'Name the customer and the offer',
    'The first step is to identify who is buying (the customer) and what they are buying (the offer). Planning before building prevents errors.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When is the exercise complete?', 
    '["When the product is created","When all criteria are met: product created, invoice prepared, link previewed, provider checked, test completed, and follow-up owner named","When you run out of time","When the invoice is sent"]'::jsonb,
    'When all criteria are met: product created, invoice prepared, link previewed, provider checked, test completed, and follow-up owner named',
    'The exercise is complete when: product is clearly named with correct price, invoice prepared for correct contact, payment link previewed (if appropriate), provider and mode checked, test results appear in records, buyer knows next steps, and a named person owns follow-up.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do after the basic payment path works?', 
    '["Immediately add all possible features","Add one improvement at a time and test the complete journey after every change","Never touch it again","Delete it and start over"]'::jsonb,
    'Add one improvement at a time and test the complete journey after every change',
    'After the basic payment path works, add improvements one at a time: recurring billing, estimates, deposits, reminders, coupons, workflows, etc. Test the complete buyer journey after every change.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
